create or replace function hpsr_private.may_change_profile_signature(target_path text) returns boolean language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or split_part(target_path,'/',1)<>auth.uid()::text or not public.is_hpsr_staff() then return false; end if; return not exists(select 1 from public.clinical_records c where c.image_asset_paths @> array[target_path] or c.released_image_asset_paths @> array[target_path]); end; $$;
